{
  "case_id": "xsu_sg_005_work_capacity_scope",
  "criteria": {
    "c01_overall_legal_correctness": {
      "label": "not_met",
      "reason": "Svaret slår fast, at ingen af punkterne indgår, og det er forkert for kommunal arbejdsevnevurdering. Kilden og rubrikken siger, at vurderingen ikke er den kommunale arbejdsevnevurdering og ikke kan sammenlignes med den. Det er ikke det samme som, at den ikke indgår. Svaret fortier desuden, at tidligere og aktuelt erhvervsarbejde indgår i vurderingen (linje 203-210). Samlet er den kategoriske konklusion for bred, og svaret overser nuancerne i kilden."
    },
    "c02_required_elements_complete": {
      "label": "not_met",
      "reason": "Svaret har målestokken (erhvervsevne under uddannelse) og udelukker de fleste punkter. Det mangler dog, at funktionsnedsættelsens art og grad samt de ressourcer, personen har, er grundlaget. Det siger heller ikke, at vurderingen er noget andet end den kommunale arbejdsevnevurdering, og at den ikke kan sammenlignes med den. Det nævner ikke, at muligheden for at finde egnet arbejde er udeladt. Det er kun listen, der dækker punktet om arbejdsgivere, arbejdsprøvning, indretning, studierelevans, lokale forhold og erhvervsevne efter uddannelsen."
    },
    "c03_direct_relevance": {
      "label": "met",
      "reason": "Svaret tager stilling til alle syv punkter i spørgsmålet og forklarer kort, hvad vurderingen fokuserer på. Der er ingen irrelevant tekst."
    },
    "c04_source_traceability": {
      "label": "not_met",
      "reason": "Svaret nævner ingen kilde, hverken lov, bekendtgørelse eller vejledning."
    },
    "c05_source_validity": {
      "label": "not_assessable",
      "reason": "Der er ikke angivet nogen kilde, så gyldigheden kan ikke vurderes."
    },
    "c06_claim_source_support": {
      "label": "not_assessable",
      "reason": "Der er ikke angivet nogen kilde, så støtten til påstandene kan ikke vurderes."
    },
    "c07_no_unsupported_legal_additions": {
      "label": "not_met",
      "reason": "Svaret tilføjer påstanden om, at kommunal arbejdsevnevurdering slet ikke indgår. Det har ikke støtte i kilderne, som kun siger, at vurderingen ikke kan sammenlignes med kommunernes. Svaret tilføjer også, at vurderingen 'tager udgangspunkt i', hvor stor en begrænsning funktionsnedsættelsen medfører for at kunne 'fungere på arbejdsmarkedet', og at dette skal give en 'betydelig reducering'. Kilden siger 'meget betydelige begrænsninger', og formuleringen om arbejdsmarkedet er ikke den samme."
    },
    "c08_qualifications_and_exceptions": {
      "label": "not_met",
      "reason": "Svaret mister den vigtige forskel mellem 'ikke den kommunale vurdering' og 'indgår ikke'. Det nævner ikke, at tidligere og aktuelt arbejde indgår, og det udelader 'meget betydelige' som tærskel. Det skriver 'betydelig reducering'."
    },
    "c09_reasoning_coherence": {
      "label": "not_met",
      "reason": "Svaret siger, at 'erhvervsevnen' ikke indgår, men beskriver derefter selv vurderingen som en vurdering af erhvervsevne under uddannelse. Det er en indre uoverensstemmelse. 'Erhvervsevnen efter uddannelsen' er det, der er udelukket, ikke erhvervsevnen som sådan. Samlet er det en skarp 'nej' til alt, mens begrundelsen delvist modsiger det."
    },
    "c10_legal_modality_precision": {
      "label": "not_met",
      "reason": "Svaret gør kildens 'kan ikke sammenlignes med' til en absolut udelukkelse ('indgår ikke'). Det omskriver tærsklen 'meget betydelige begrænsninger' til 'betydelig reducering'. Det giver en upræcis modalitet."
    }
  },
  "xhaile_coverage": {
    "A15": {
      "label": "partial",
      "reason": "Svaret dækker, at arbejdsprøvning, særlig indretning, arbejdsgiverkontakt, studierelevans, lokale forhold og erhvervsevne efter uddannelsen ikke indgår, og at vurderingen gælder erhvervsevne under uddannelse. Det nævner ikke tærsklen 'meget betydelige begrænsninger' korrekt (skriver 'betydelig reducering'), ordblindeeksemplet, 'de ressourcer, personen har' eller vanskeligheden ved at finde arbejde."
    }
  },
  "overall_notes": "Svaret er delvist korrekt for de fleste udelukkede punkter, men det er forkert og for kategorisk for kommunal arbejdsevnevurdering. Kilden siger, at vurderingen ikke kan sammenlignes med den, ikke at den ikke må indgå. Der er ingen kildeangivelse, og tærsklen er omformuleret. C05 og C06 er not_assessable efter reglen om manglende kilde."
}

